/** * Proxy fetch helper for Next.js API routes (/api/proxy/*). * With httpOnly cookies, auth is via cookies (credentials: include), * no need to manually attach Bearer tokens from localStorage. */ export function useApiProxy() {
  async function proxyFetch(input: string | URL | Request, init?: RequestInit) {
    const headers: Record<string, string> = { ...(init?.headers as Record<string, string>) };
    if (init?.body != null) {
      headers['Content-Type'] = 'application/json';
    }
    return fetch(input, { ...init, headers, credentials: 'include' });
  }
  return { fetch: proxyFetch };
}
export async function apiProxyFetch(input: string | URL | Request, init?: RequestInit) {
  const headers: Record<string, string> = { ...(init?.headers as Record<string, string>) };
  if (init?.body != null) {
    headers['Content-Type'] = 'application/json';
  }
  return fetch(input, { ...init, headers, credentials: 'include' });
}
